analytic_control.program:
options nodate nonumber nocenter;
ods graphics off;
data corners;
input x z y;
datalines;
-1 -1 12
-1 1 4
1 -1 14
1 1 10
0 . 1000
;
run;
proc reg data=corners;
model y=x z;
run;
refit;
run;
delete z;
run;
print;
delete x;
refit;
print;
run;
add z x;
refit;
print;
run;
quit;

manual_delete_control.program:
